#!/usr/bin/env python3
import sys,json
from pathlib import Path
values={"dns":"OK 192.0.2.10","ping":"OK 30ms","port443":"REFUSED","route":"via 10.0.0.1","firewall":"ALLOW outbound","proxy":"none","capture":"SYN without response"}
name=sys.argv[1] if len(sys.argv)>1 else ''
if name not in values: raise SystemExit(2)
if name=='capture' and sys.argv[2:]!=['--seconds','10']: raise SystemExit(3)
with Path('diag-calls.txt').open('a') as f: f.write(name+'\n')
print(values[name])

